"""GENERATED by StairPath/sync_pyrevit_lib.py from rules.py and engine.py -- do not edit.

The command line sends this engine to Revit as text (revit.action_code): RULES runs as a module named
``rules``, ENGINE runs in the listener's namespace with ``rules`` and ``Check`` already bound.
"""

RULES = r'''"""The office standard for Stair Path annotations, as plain data -> plain data (no Revit API).

engine.py reads the model into the shapes below, asks these functions what to place, and places it.
IronPython 2.7 + CPython 3.

Shapes (lengths in feet, like the Revit API):
  level  {"id", "name", "elev"}
  stair  {"id", "base", "top"            -- level names from the Base / Top Level parameters (or None)
          "base_elev", "top_elev"        -- level elevation + base / top offset (None when unknown)
          "box": (minx, miny, maxx, maxy), "run": (dx, dy) of the first flight (BaseElevation 0)}
  view   {"id", "name", "scale", "level", "crop": (minx, miny, maxx, maxy) or None, "visible": [stair ids]}
  type   {"id", "family", "name"}
"""

import re

MM_PER_FT = 304.8
FIXED = "Fixed Up Direction"
AUTO = "Automatic Up/Down Direction"
SCALES = (500, 200, 100)
TEXT_SCALES = (200, 100)            # 1:500 shows arrows only

# Every setting of a run; the button keeps one set per model (distances are tuned per building).
DEFAULTS = {
    "views": "open",                # open | name -- the open plan views, or every plan view whose name contains:
    "name_filter": "GA Plan",
    "clear": "views",               # views | model -- existing stair paths cleared in the target views / whole model
    "directional": True,            # text placed away from the way each stair's first flight runs
    "dir_x_mm": 300.0,              # length > width, run toward +X: text this far on the -X side
    "dir_y_mm": 300.0,              # width > length: text this far against the run (-Y for a +Y run, +Y for -Y)
    "std_x_200": 600.0,             # standard offsets (the -X run of an X stair, and no-direction cases)
    "std_y_200": 200.0,
    "std_x_100": 400.0,
    "std_y_100": 200.0,
    "sweep": True,                  # tag every other visible stair: Automatic Up/Down, both texts
    "room_tags": True,              # nudge room tags off the stair paths; Staircase tags back inside their room
    "tag_nudge_mm": 300.0,
    "tag_pad_mm": 400.0,
    "staircase_keyword": "stair",
    "check_dimensions": True,       # report stair paths that overlap a dimension string (nothing is moved)
    "create_types": False,          # duplicate each family's "Standard" type into a missing "Standard 1-xxx"
    "core_tol_mm": 1500.0,          # flights whose plan centres are this close (or plans overlap) share a core
    "level_tol_mm": 300.0,          # a flight's base / top snaps to the level within this distance
}

# columns of the annotation list (CSV) the button and the command line write
CSV_FIELDS = ["view", "scale", "level", "core", "kind", "stair", "result", "path", "offset_mm", "why"]

NUMBERS = ("dir_x_mm", "dir_y_mm", "std_x_200", "std_y_200", "std_x_100", "std_y_100", "tag_nudge_mm",
           "tag_pad_mm", "core_tol_mm", "level_tol_mm")


class Check(object):
    def __init__(self, label, ok, detail=""):
        self.label, self.ok, self.detail = label, ok, detail

    @property
    def mark(self):
        return "OK  " if self.ok is True else ("WARN" if self.ok is None else "FAIL")

    def __str__(self):
        return "[%s] %s%s" % (self.mark, self.label, (" -- " + self.detail) if self.detail else "")


def settings(values=None):
    """DEFAULTS updated with ``values`` (strings from the window or the config are converted; bad ones dropped)."""
    s = dict(DEFAULTS)
    for key, v in (values or {}).items():
        if key not in DEFAULTS or v is None:
            continue
        default = DEFAULTS[key]
        try:
            if isinstance(default, bool):
                s[key] = v if isinstance(v, bool) else str(v).strip().lower() in ("1", "true", "yes", "on")
            elif isinstance(default, float):
                s[key] = float(v)
            else:
                s[key] = u"%s" % v
        except (TypeError, ValueError):
            pass
    if s["views"] not in ("open", "name"):
        s["views"] = "open"
    if s["clear"] not in ("views", "model"):
        s["clear"] = "views"
    return s


def check_settings(s):
    """FAIL checks for distances that make no sense (negative, or tolerances of zero)."""
    out = []
    for key in NUMBERS:
        if s[key] < 0:
            out.append(Check("Setting %s" % key, False, "must not be negative (%s)" % s[key]))
    for key in ("core_tol_mm", "level_tol_mm"):
        if s[key] <= 0:
            out.append(Check("Setting %s" % key, False, "must be more than 0"))
    if s["views"] == "name" and not s["name_filter"].strip():
        out.append(Check("Views", False, "type the text the plan view names contain"))
    return out


# ------------------------------------------------------------ family types (fuzzy names)

def _norm(text):
    return re.sub(r"[^a-z0-9]+", " ", (text or u"").lower()).strip()


def family_kind(family):
    """FIXED / AUTO for a Stair Path family name, loosely ("Fixed Up Direction", "automatic up-down", ...)."""
    n = _norm(family)
    if "fixed" in n:
        return FIXED
    if "auto" in n:
        return AUTO
    return None


def type_scale(name):
    """The scale a type name is meant for: 'Standard 1-500' / '1:200' / '1/100' / 'Standard 100' -> 500 / 200 / 100."""
    m = re.search(r"1\s*[-:/_ ]\s*(\d{2,4})(?!\d)", name or u"")
    if not m:
        m = re.search(r"(?<!\d)(\d{3})\s*$", (name or u"").strip())
    return int(m.group(1)) if m else None


def pick_type(types, kind, scale):
    """The type of family ``kind`` for ``scale``: a 'Standard' name first, then the shortest name. None if none."""
    hits = [t for t in types if family_kind(t["family"]) == kind and type_scale(t["name"]) == scale]
    if not hits:
        return None
    hits.sort(key=lambda t: ("standard" not in _norm(t["name"]), len(t["name"]), t["name"]))
    return hits[0]


def missing_types(types, scales):
    """[(kind, scale)] needed for these view scales but not in the model."""
    need = []
    for sc in sorted(set(scales), reverse=True):
        kinds = (AUTO,) if sc == 500 else (FIXED, AUTO)
        for kind in kinds:
            if pick_type(types, kind, sc) is None:
                need.append((kind, sc))
    return need


def type_to_create(types, kind, scale):
    """(source type, new name) to duplicate for a missing type: the family's plain 'Standard' type (or any)."""
    fam = [t for t in types if family_kind(t["family"]) == kind]
    if not fam:
        return None, None
    fam.sort(key=lambda t: (_norm(t["name"]) != "standard", type_scale(t["name"]) is not None, t["name"]))
    return fam[0], u"Standard 1-%d" % scale


# ------------------------------------------------------------ levels and cores

def snap_level(levels, elev, tol):
    """Name of the level nearest ``elev`` (feet) within ``tol``, else None."""
    if elev is None:
        return None
    best = None
    for lv in levels:
        d = abs(lv["elev"] - elev)
        if d <= tol and (best is None or d < best[0]):
            best = (d, lv["name"])
    return best[1] if best else None


def flight_levels(stair, levels, tol):
    """(base, top, note) -- each end snapped to a level from its real elevation (level + offset), falling back
    to the parameter's level. note says when the parameter names a different level than the elevation."""
    base = snap_level(levels, stair.get("base_elev"), tol) or stair.get("base")
    top = snap_level(levels, stair.get("top_elev"), tol) or stair.get("top")
    notes = []
    if stair.get("base") and base != stair.get("base"):
        notes.append("base %s (parameter: %s)" % (base, stair.get("base")))
    if stair.get("top") and top != stair.get("top"):
        notes.append("top %s (parameter: %s)" % (top, stair.get("top")))
    return base, top, "; ".join(notes)


def _centre(box):
    return ((box[0] + box[2]) / 2.0, (box[1] + box[3]) / 2.0)


def _overlap_ratio(a, b):
    w = min(a[2], b[2]) - max(a[0], b[0])
    h = min(a[3], b[3]) - max(a[1], b[1])
    if w <= 0 or h <= 0:
        return 0.0
    small = min((a[2] - a[0]) * (a[3] - a[1]), (b[2] - b[0]) * (b[3] - b[1]))
    return (w * h) / small if small > 0 else 0.0


def same_core(a, b, tol):
    ca, cb = _centre(a["box"]), _centre(b["box"])
    near = ((ca[0] - cb[0]) ** 2 + (ca[1] - cb[1]) ** 2) ** 0.5 <= tol
    return near or _overlap_ratio(a["box"], b["box"]) >= 0.5


def build_cores(stairs, levels, s):
    """Group the flights into stair cores (stacked in plan) with their resolved base / top levels.

    Returns (cores, skipped, notes): cores = [{"name", "flights": [{"id", "base", "top"}]}] ordered by plan
    position; skipped = [(id, why)] for flights without two different levels; notes = [(id, text)].
    """
    tol_lv = s["level_tol_mm"] / MM_PER_FT
    order = dict((lv["name"], i) for i, lv in enumerate(levels))
    flights, skipped, notes = [], [], []
    for st in stairs:
        base, top, note = flight_levels(st, levels, tol_lv)
        if note:
            notes.append((st["id"], note))
        if base not in order or top not in order:
            skipped.append((st["id"], "no base or top level"))
        elif order[base] >= order[top]:
            skipped.append((st["id"], "does not climb from one level to a higher one (%s -> %s)" % (base, top)))
        else:
            flights.append(dict(st, base=base, top=top))
    tol = s["core_tol_mm"] / MM_PER_FT
    parent = list(range(len(flights)))

    def root(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    for i in range(len(flights)):
        for j in range(i + 1, len(flights)):
            if same_core(flights[i], flights[j], tol):
                parent[root(j)] = root(i)
    groups = {}
    for i, f in enumerate(flights):
        groups.setdefault(root(i), []).append(f)
    ordered = sorted(groups.values(), key=lambda fs: (round(min(_centre(f["box"])[0] for f in fs), 3),
                                                       round(min(_centre(f["box"])[1] for f in fs), 3)))
    cores = []
    for n, fs in enumerate(ordered):
        fs.sort(key=lambda f: (order[f["base"]], f["id"]))
        cores.append({"name": "Core %s" % _letters(n), "flights": [{"id": f["id"], "base": f["base"],
                                                                     "top": f["top"]} for f in fs]})
    return cores, skipped, notes


def _letters(n):
    out = ""
    n += 1
    while n:
        n, r = divmod(n - 1, 26)
        out = chr(65 + r) + out
    return out


def up_down(cores):
    """({level: [(core, stair id)]} going up, {level: [(core, stair id)]} arriving from below).

    Duplicate flights of one core at the same base (or top) level: the newest element (highest id) wins."""
    ups, downs = {}, {}
    for core in cores:
        by_base, by_top = {}, {}
        for f in core["flights"]:
            by_base.setdefault(f["base"], []).append(f["id"])
            by_top.setdefault(f["top"], []).append(f["id"])
        for lvl, ids in by_base.items():
            ups.setdefault(lvl, []).append((core["name"], max(ids)))
        for lvl, ids in by_top.items():
            downs.setdefault(lvl, []).append((core["name"], max(ids)))
    return ups, downs


def pass_through(cores, levels, level):
    """{core: stair id} of a flight that runs through ``level`` (base below it, top above it)."""
    order = dict((lv["name"], i) for i, lv in enumerate(levels))
    li = order.get(level)
    out = {}
    if li is None:
        return out
    for core in cores:
        ids = [f["id"] for f in core["flights"] if order[f["base"]] < li < order[f["top"]]]
        if ids:
            out[core["name"]] = max(ids)
    return out


# ------------------------------------------------------------ what to place in each view

def boxes_overlap(a, b):
    return not (a[2] < b[0] or a[0] > b[2] or a[3] < b[1] or a[1] > b[3])


def style(scale, kind):
    """(family kind, show up text, show down text, offsets set) for an annotation of ``kind`` at ``scale``.

    kind: up | down | through (a flight passing the level, in place of a hidden arriving one) | sweep.
    show_down None = leave it alone (Fixed Up Direction has no Show Down Text)."""
    if scale == 500:
        return AUTO, False, False, ()
    if kind == "up":
        return FIXED, True, None, ("up",)
    if kind == "down":
        return AUTO, False, True, ("down",)
    return AUTO, True, True, ("up", "down")


def text_offset(stair, scale, s):
    """(x, y) offset of the Up / Down text in mm, from the stair's own plan proportions and run direction.

    Length >= width (travel along X): a run toward +X puts the text dir_x_mm on the -X side; a run toward -X
    (or unknown) keeps the standard distance on the +X side. Width > length (travel along Y): the text goes
    dir_y_mm against the run (-Y for a +Y run, +Y for a -Y run); unknown -> the standard distance on +Y."""
    if scale not in TEXT_SCALES:
        return (0.0, 0.0)
    box = stair["box"]
    dx, dy = stair.get("run") or (0.0, 0.0)
    std_x, std_y = s["std_x_%d" % scale], s["std_y_%d" % scale]
    if box[2] - box[0] >= box[3] - box[1]:
        if s["directional"] and dx > 1e-9:
            return (-s["dir_x_mm"], 0.0)
        return (std_x, 0.0)
    if s["directional"] and abs(dy) > 1e-9:
        return (0.0, -s["dir_y_mm"] if dy > 0 else s["dir_y_mm"])
    return (0.0, std_y)


def plan_view(view, cores, levels, ups, downs, stairs_by_id):
    """The annotations one view should get: [{"kind", "core", "stair", "fallback"}] plus notes for flights
    outside the view's crop. A Down whose flight Revit will not show here falls back to ``fallback`` (a flight
    of the same core passing through the level), placed as 'through'."""
    level = view["level"]
    jobs, notes = [], []
    through = pass_through(cores, levels, level)

    def in_crop(sid):
        st = stairs_by_id.get(sid)
        return view.get("crop") is None or st is None or boxes_overlap(st["box"], view["crop"])

    for core, sid in sorted(ups.get(level, [])):
        if in_crop(sid):
            jobs.append({"kind": "up", "core": core, "stair": sid, "fallback": None})
        else:
            notes.append("%s: %s Up (stair %d) is outside the crop region -- skipped" % (view["name"], core, sid))
    for core, sid in sorted(downs.get(level, [])):
        fb = through.get(core)
        if in_crop(sid) or (fb is not None and in_crop(fb)):
            jobs.append({"kind": "down", "core": core, "stair": sid, "fallback": fb})
        else:
            notes.append("%s: %s Down (stair %d) is outside the crop region -- skipped" % (view["name"], core, sid))
    return jobs, notes


def sweep_jobs(view, tagged):
    """Visible stairs in the view that still have no stair path: Automatic Up/Down with both texts."""
    return [{"kind": "sweep", "core": None, "stair": sid, "fallback": None}
            for sid in sorted(set(view.get("visible") or [])) if sid not in tagged]


def scale_problems(views):
    """Views at a scale the standard does not cover (only 1:500, 1:200 and 1:100 are)."""
    return [v for v in views if v["scale"] not in SCALES]
'''

ENGINE = r'''"""Stair Path by Netbuild -- the part that talks to Revit (IronPython 2.7, inside Revit, from the pyRevit button).

read_model() turns the model into rules.py's plain shapes; run() places the annotations those rules ask for:
Check (plan only, nothing changes) -> Trial run (everything placed, then rolled back) -> Apply (one Undo
entry: 'Stair Path by Netbuild'). View templates and View Range are never changed: a Down that Revit cannot
show is reported as a gap for the user to decide.
"""

from Autodesk.Revit.DB import (BuiltInCategory, BuiltInParameter, ElementId, FailureProcessingResult,
                               FailureSeverity, FilteredElementCollector, IFailuresPreprocessor, Level,
                               LinkElementId, Transaction, TransactionGroup, TransactionStatus, ViewPlan,
                               ViewType, XYZ)
from Autodesk.Revit.DB.Architecture import StairsPath
from System.Collections.Generic import List


TITLE = "Stair Path by Netbuild"
FT = rules.MM_PER_FT


def iid(eid):
    if eid is None:
        return -1
    v = getattr(eid, "Value", None)          # Revit 2024+ (Int64); IntegerValue is gone in 2026
    if v is None:
        v = eid.IntegerValue
    return int(v)


def _txt(x):
    try:
        return u"%s" % x
    except Exception:
        return repr(x)


def _param(el, bip):
    try:
        return el.get_Parameter(getattr(BuiltInParameter, bip))
    except Exception:
        return None


def _level_param(doc, el, bip):
    p = _param(el, bip)
    if p is None:
        return None
    lv = doc.GetElement(p.AsElementId())
    return lv if isinstance(lv, Level) else None


def _double(el, bip):
    p = _param(el, bip)
    try:
        return p.AsDouble() if p is not None else 0.0
    except Exception:
        return 0.0


def _string(el, bip):
    p = _param(el, bip)
    try:
        return p.AsString() if p is not None else None
    except Exception:
        return None


def _elements(doc, cat, view_id=None, types=False):
    coll = FilteredElementCollector(doc, view_id) if view_id is not None else FilteredElementCollector(doc)
    coll = coll.OfCategory(getattr(BuiltInCategory, cat))
    coll = coll.WhereElementIsElementType() if types else coll.WhereElementIsNotElementType()
    return list(coll.ToElements())


def _xy_box(bb):
    return (bb.Min.X, bb.Min.Y, bb.Max.X, bb.Max.Y)


def _first_run(doc, stair):
    """Plan travel (dx, dy) of the stair's own first flight: the run at BaseElevation 0 (or the lowest run) --
    GetStairsRuns() order is not the physical up-sequence."""
    runs = []
    for rid in stair.GetStairsRuns():
        run = doc.GetElement(rid)
        if run is not None:
            runs.append((getattr(run, "BaseElevation", 0.0), run))
    if not runs:
        return (0.0, 0.0)
    runs.sort(key=lambda r: r[0])
    try:
        curves = list(runs[0][1].GetStairsPath())
        p0, p1 = curves[0].GetEndPoint(0), curves[-1].GetEndPoint(1)
        return (p1.X - p0.X, p1.Y - p0.Y)
    except Exception:
        return (0.0, 0.0)


def _crop(view):
    if not getattr(view, "CropBoxActive", False):
        return None
    try:
        bb = view.CropBox
        t = bb.Transform
        pts = [t.OfPoint(XYZ(x, y, bb.Min.Z)) for x in (bb.Min.X, bb.Max.X) for y in (bb.Min.Y, bb.Max.Y)]
        return (min(p.X for p in pts), min(p.Y for p in pts), max(p.X for p in pts), max(p.Y for p in pts))
    except Exception:
        return None


def _template(doc, view):
    """(template name, True when that template controls View Range) -- (None, False) without a template."""
    tid = getattr(view, "ViewTemplateId", None)
    tpl = doc.GetElement(tid) if tid is not None and iid(tid) > 0 else None
    if tpl is None:
        return None, False
    try:
        free = set(iid(i) for i in tpl.GetNonControlledTemplateParameterIds())
        controls = iid(ElementId(BuiltInParameter.PLAN_VIEW_RANGE)) not in free
    except Exception:
        controls = True
    return _txt(tpl.Name), controls


def target_views(doc, uidoc, s):
    if s["views"] == "name":
        want = s["name_filter"].strip().lower()
        views = [v for v in FilteredElementCollector(doc).OfClass(ViewPlan).ToElements()
                 if want in _txt(v.Name).lower()]
    else:
        views = [doc.GetElement(uv.ViewId) for uv in uidoc.GetOpenUIViews()] if uidoc is not None else []
    out = []
    for v in views:
        if (isinstance(v, ViewPlan) and not v.IsTemplate and v.ViewType == ViewType.FloorPlan
                and getattr(v, "GenLevel", None) is not None):
            out.append(v)
    return sorted(out, key=lambda v: _txt(v.Name))


def read_model(doc, uidoc, s):
    """The model as rules.py shapes, plus the Revit objects behind them ("_stairs", "_views", "_types")."""
    levels = sorted([{"id": iid(lv.Id), "name": _txt(lv.Name), "elev": lv.Elevation}
                     for lv in FilteredElementCollector(doc).OfClass(Level).ToElements()],
                    key=lambda lv: (lv["elev"], lv["name"]))
    stairs, by_id = [], {}
    for st in _elements(doc, "OST_Stairs"):
        if not hasattr(st, "GetStairsRuns"):
            continue                                     # not a component stair: Revit cannot path it
        bb = st.get_BoundingBox(None)
        if bb is None:
            continue
        base, top = _level_param(doc, st, "STAIRS_BASE_LEVEL_PARAM"), _level_param(doc, st, "STAIRS_TOP_LEVEL_PARAM")
        base_elev = base.Elevation + _double(st, "STAIRS_BASE_OFFSET") if base is not None else None
        top_elev = top.Elevation + _double(st, "STAIRS_TOP_OFFSET") if top is not None else None
        if top_elev is None and base_elev is not None and getattr(st, "Height", None):
            top_elev = base_elev + st.Height
        sid = iid(st.Id)
        stairs.append({"id": sid, "base": _txt(base.Name) if base is not None else None,
                       "top": _txt(top.Name) if top is not None else None, "base_elev": base_elev,
                       "top_elev": top_elev, "box": _xy_box(bb), "run": _first_run(doc, st)})
        by_id[sid] = st
    views, view_objs = [], {}
    for v in target_views(doc, uidoc, s):
        visible = [iid(e.Id) for e in _elements(doc, "OST_Stairs", v.Id) if iid(e.Id) in by_id]
        tpl, controls = _template(doc, v)
        views.append({"id": iid(v.Id), "name": _txt(v.Name), "scale": v.Scale, "level": _txt(v.GenLevel.Name),
                      "crop": _crop(v), "visible": visible, "template": tpl, "template_range": controls})
        view_objs[iid(v.Id)] = v
    types, type_objs = [], {}
    for t in _elements(doc, "OST_StairsPaths", types=True):
        family = _string(t, "ALL_MODEL_FAMILY_NAME") or _txt(getattr(t, "FamilyName", ""))
        name = _string(t, "ALL_MODEL_TYPE_NAME") or _string(t, "SYMBOL_NAME_PARAM") or ""
        types.append({"id": iid(t.Id), "family": family, "name": name})
        type_objs[iid(t.Id)] = t
    return {"doc": doc.Title, "levels": levels, "stairs": stairs, "views": views, "types": types,
            "_stairs": by_id, "_views": view_objs, "_types": type_objs}


class _Quiet(IFailuresPreprocessor):
    """Warnings are logged and dismissed; any error rolls the step back."""

    def __init__(self, msgs):
        self.msgs = msgs

    def PreprocessFailures(self, fa):
        err = False
        for f in list(fa.GetFailureMessages()):
            text = _txt(f.GetDescriptionText()).strip()
            if f.GetSeverity() == FailureSeverity.Warning:
                self.msgs.append("warning: " + text)
                fa.DeleteWarning(f)
            else:
                self.msgs.append("error: " + text)
                err = True
        return FailureProcessingResult.ProceedWithRollBack if err else FailureProcessingResult.Continue


def _step(doc, name, msgs, fn):
    t = Transaction(doc, "%s -- %s" % (TITLE, name))
    opts = t.GetFailureHandlingOptions()
    opts.SetFailuresPreprocessor(_Quiet(msgs))
    t.SetFailureHandlingOptions(opts)
    t.Start()
    try:
        out = fn()
    except Exception:
        t.RollBack()
        raise
    status = t.Commit()
    if status != TransactionStatus.Committed:
        raise RuntimeError("%s: Revit did not commit (%s) -- %s" % (name, status, "; ".join(msgs[-3:])))
    return out


class Run(object):
    """One Check / Trial run / Apply. ``report()`` gives (checks, lines, rows) for the window and the log."""

    def __init__(self, doc, uidoc, values=None):
        self.doc, self.uidoc = doc, uidoc
        self.s = rules.settings(values)
        self.checks, self.lines, self.rows, self.msgs = [], [], [], []

    # ------------------------------------------------------------ plan
    def plan(self):
        s = self.s
        self.checks += rules.check_settings(s)
        m = self.model = read_model(self.doc, self.uidoc, s)
        views = m["views"]
        where = "open plan views" if s["views"] == "open" else "plan views named '*%s*'" % s["name_filter"]
        self.checks.append(Check("Target views", bool(views), "%d %s" % (len(views), where) if views else
                                 "no %s -- open the floor plans to annotate, or pick views by name" % where))
        odd = rules.scale_problems(views)
        if odd:
            self.checks.append(Check("Views at other scales", None, "skipped (only 1:500, 1:200 and 1:100 are in "
                                     "the standard): %s" % ", ".join("%s (1:%d)" % (v["name"], v["scale"])
                                                                     for v in odd)))
        self.views = [v for v in views if v["scale"] in rules.SCALES]
        self.missing = rules.missing_types(m["types"], [v["scale"] for v in self.views])
        for kind, sc in self.missing:
            src, new = rules.type_to_create(m["types"], kind, sc)
            if s["create_types"] and src is not None:
                self.checks.append(Check("Stair path type %s : 1-%d" % (kind, sc), None,
                                         "not in the model -- '%s : %s' will be created from '%s'"
                                         % (kind, new, src["name"])))
            else:
                self.checks.append(Check("Stair path type %s : 1-%d" % (kind, sc), False,
                                         "not in the model (names are matched loosely, e.g. 'Standard 1-%d')%s"
                                         % (sc, "" if src is None else " -- tick 'Create missing types'")))
        self.cores, skipped, notes = rules.build_cores(m["stairs"], m["levels"], s)
        self.ups, self.downs = rules.up_down(self.cores)
        self.checks.append(Check("Stair cores", True if self.cores else None, "%d core(s), %d flight(s) of %d stairs" % (
            len(self.cores), sum(len(c["flights"]) for c in self.cores), len(m["stairs"]))))
        for c in self.cores:
            fl = c["flights"]
            self.lines.append("  %s: %d flight(s) %s -> %s  [%s]" % (
                c["name"], len(fl), fl[0]["base"], max(fl, key=lambda f: self._order(f["top"]))["top"],
                ", ".join("%d %s->%s" % (f["id"], f["base"], f["top"]) for f in fl)))
        if skipped:
            self.checks.append(Check("Stairs left out of the Up/Down chain", None, "%d (the sweep still tags them "
                                     "where visible): %s" % (len(skipped), "; ".join("%d %s" % x for x in skipped))))
        if notes:
            self.checks.append(Check("Base / top taken from the real elevation", None, "; ".join(
                "%d %s" % n for n in notes)))
        by_id = dict((st["id"], st) for st in m["stairs"])
        self.jobs = []
        for v in self.views:
            jobs, outside = rules.plan_view(v, self.cores, m["levels"], self.ups, self.downs, by_id)
            self.jobs.append((v, jobs))
            self.lines.extend("  " + n for n in outside)
            ups = len([j for j in jobs if j["kind"] == "up"])
            self.lines.append("  %s (1:%d, %s): Up x%d, Down x%d" % (v["name"], v["scale"], v["level"], ups,
                                                                     len(jobs) - ups))
        self.by_id = by_id
        return self.ok()

    def _order(self, name):
        for i, lv in enumerate(self.model["levels"]):
            if lv["name"] == name:
                return i
        return -1

    def ok(self):
        return not [c for c in self.checks if c.ok is False]

    # ------------------------------------------------------------ place
    def type_id(self, kind, scale):
        t = rules.pick_type(self.model["types"], kind, scale)
        return self.model["_types"][t["id"]].Id if t else None

    def place(self, view, sid, kind):
        """Create one stair path; returns it (Revit raises when the flight is not visible in the view)."""
        scale = view["scale"]
        fam, show_up, show_down, offsets = rules.style(scale, kind)
        type_id = self.type_id(fam, scale)
        if type_id is None:
            raise LookupError("no %s type for 1:%d" % (fam, scale))
        st = self.model["_stairs"][sid]
        sp = StairsPath.Create(self.doc, LinkElementId(st.Id), type_id, self.model["_views"][view["id"]].Id)
        sp.ShowUpText = show_up
        if show_down is not None:
            sp.ShowDownText = show_down
        ox, oy = rules.text_offset(self.by_id[sid], scale, self.s)
        vec = XYZ(ox / FT, oy / FT, 0)
        if "up" in offsets:
            sp.UpTextOffset = vec
        if "down" in offsets:
            sp.DownTextOffset = vec
        return sp, (ox, oy)

    def row(self, view, job, result, sid, sp=None, offset=None, why=""):
        self.rows.append({"view": view["name"], "scale": view["scale"], "level": view["level"],
                          "core": job.get("core") or "", "kind": job["kind"], "stair": sid, "result": result,
                          "path": iid(sp.Id) if sp is not None else "",
                          "offset_mm": "%.0f, %.0f" % offset if offset else "", "why": why})

    def create_types(self):
        made = []
        for kind, sc in self.missing:
            src, new = rules.type_to_create(self.model["types"], kind, sc)
            if src is None:
                continue
            t = self.model["_types"][src["id"]].Duplicate(new)
            self.model["types"].append({"id": iid(t.Id), "family": src["family"], "name": new})
            self.model["_types"][iid(t.Id)] = t
            made.append("%s : %s" % (kind, new))
        return made

    def clear(self):
        paths = _elements(self.doc, "OST_StairsPaths")
        if self.s["clear"] == "views":
            keep = set(v["id"] for v in self.views)
            paths = [p for p in paths if iid(p.OwnerViewId) in keep]
        if paths:
            self.doc.Delete(List[ElementId]([p.Id for p in paths]))
        return len(paths)

    def place_main(self):
        self.created, self.gaps, self.failed, self.through = [], [], [], 0
        for v, jobs in self.jobs:
            for job in jobs:
                try:
                    sp, off = self.place(v, job["stair"], job["kind"])
                    self.created.append((v, sp))
                    self.row(v, job, "placed", job["stair"], sp, off)
                    continue
                except Exception as e:
                    first = _txt(e)
                if job["kind"] == "down" and job["fallback"] is not None:
                    try:
                        sp, off = self.place(v, job["fallback"], "through")
                        self.created.append((v, sp))
                        self.through += 1
                        self.row(v, job, "through", job["fallback"], sp, off,
                                 "stair %d not visible here -- passing flight used" % job["stair"])
                        continue
                    except Exception as e:
                        first += " / passing flight %d: %s" % (job["fallback"], _txt(e))
                if job["kind"] == "down":
                    self.gaps.append((v, job, first))
                    self.row(v, job, "gap", job["stair"], why=first)
                else:
                    self.failed.append((v, job, first))
                    self.row(v, job, "not placed", job["stair"], why=first)

    def tagged(self):
        out = {}
        for p in _elements(self.doc, "OST_StairsPaths"):
            try:
                out.setdefault(iid(p.OwnerViewId), set()).add(iid(p.StairsId.HostElementId))
            except Exception:
                pass
        return out

    def sweep(self):
        done = []
        tagged = self.tagged()
        for v in self.views:
            for job in rules.sweep_jobs(v, tagged.get(v["id"], set())):
                try:
                    sp, off = self.place(v, job["stair"], "sweep")
                except Exception as e:
                    self.row(v, job, "not placed", job["stair"], why=_txt(e))
                    continue
                self.created.append((v, sp))
                done.append((v, job["stair"]))
                self.row(v, job, "placed", job["stair"], sp, off)
        return done

    def _path_boxes(self, view_obj, pad):
        out = []
        for v, sp in self.created:
            if v["id"] != iid(view_obj.Id):
                continue
            bb = sp.get_BoundingBox(view_obj)
            if bb is not None:
                out.append((iid(sp.Id), (bb.Min.X - pad, bb.Min.Y - pad, bb.Max.X + pad, bb.Max.Y + pad)))
        return out

    def room_tags(self):
        nudge, pad = self.s["tag_nudge_mm"] / FT, self.s["tag_pad_mm"] / FT
        word = self.s["staircase_keyword"].strip().lower()
        moved, back = 0, 0
        for v in self.views:
            view = self.model["_views"][v["id"]]
            boxes = [b for _, b in self._path_boxes(view, pad)]
            tags = _elements(self.doc, "OST_RoomTags", view.Id)
            for tag in tags:
                tbb = tag.get_BoundingBox(view)
                loc = getattr(tag, "Location", None)
                if tbb is None or not hasattr(loc, "Point"):
                    continue
                if [b for b in boxes if rules.boxes_overlap(_xy_box(tbb), b)]:
                    pt = loc.Point
                    loc.Point = XYZ(pt.X, pt.Y + nudge, pt.Z)
                    moved += 1
            if not word:
                continue
            for tag in tags:
                room = getattr(tag, "Room", None)
                loc = getattr(tag, "Location", None)
                if room is None or not hasattr(loc, "Point"):
                    continue
                if word not in (_string(room, "ROOM_NAME") or "").lower():
                    continue
                rpt = getattr(room.Location, "Point", None)
                pt = loc.Point
                if rpt is None or room.IsPointInRoom(XYZ(pt.X, pt.Y, rpt.Z + 0.5)):
                    continue
                loc.Point = XYZ(rpt.X, rpt.Y, pt.Z)
                back += 1
        return moved, back

    def dimension_overlaps(self):
        out = []
        for v in self.views:
            view = self.model["_views"][v["id"]]
            boxes = self._path_boxes(view, 0.0)
            if not boxes:
                continue
            for d in _elements(self.doc, "OST_Dimensions", view.Id):
                bb = d.get_BoundingBox(view)
                if bb is None:
                    continue
                for pid, b in boxes:
                    if rules.boxes_overlap(_xy_box(bb), b):
                        out.append("%s: stair path %d overlaps dimension %d" % (v["name"], pid, iid(d.Id)))
        return out

    def gap_text(self, v, job, why):
        text = "%s (%s): %s Down -- stair %d is not visible in this view and no flight of %s passes through %s" % (
            v["name"], v["level"], job["core"], job["stair"], job["core"], v["level"])
        if v.get("template") and v.get("template_range"):
            text += (". View Range is set by view template '%s': extending it would change every view using "
                     "that template, so nothing was changed -- decide in Revit (or ask the template owner)"
                     % v["template"])
        else:
            text += ". Extend this view's View Range (bottom / view depth) to show the arriving flight"
        return text + "  [%s]" % why

    # ------------------------------------------------------------ run
    def run(self, action):
        """action: plan | trial | apply. Returns True when nothing FAILed."""
        if not self.plan() or action == "plan":
            if action != "plan":
                self.checks.append(Check("Not run", False, "fix the FAIL lines first"))
            return self.ok()
        doc, s = self.doc, self.s
        tg = TransactionGroup(doc, TITLE)
        tg.Start()
        try:
            made = _step(doc, "types", self.msgs, self.create_types) if s["create_types"] and self.missing else []
            cleared = _step(doc, "clear", self.msgs, self.clear)
            _step(doc, "place", self.msgs, self.place_main)
            swept = _step(doc, "sweep", self.msgs, self.sweep) if s["sweep"] else []
            moved, back = _step(doc, "room tags", self.msgs, self.room_tags) if s["room_tags"] else (0, 0)
            dims = self.dimension_overlaps() if s["check_dimensions"] else []
            if action == "trial":
                tg.RollBack()
            else:
                tg.Assimilate()
        except Exception:
            if tg.HasStarted():
                tg.RollBack()
            raise
        main = len(self.created) - len(swept)
        if made:
            self.checks.append(Check("Stair path types created", True, ", ".join(made)))
        self.checks.append(Check("Cleared", True, "%d existing stair path(s) in the %s" % (
            cleared, "target views" if s["clear"] == "views" else "whole model")))
        self.checks.append(Check("Up / Down placed", True, "%d (%d Down via a flight passing through the level)"
                                 % (main, self.through)))
        if s["sweep"]:
            self.checks.append(Check("Other visible stairs tagged", True, "%d (Automatic Up/Down, both texts)"
                                     % len(swept)))
        for v, job, why in self.failed:
            self.checks.append(Check("Up not placed", None, "%s: %s stair %d -- %s" % (v["name"], job["core"],
                                                                                    job["stair"], why)))
        if self.gaps:
            self.checks.append(Check("Down gaps", None, "%d level(s) without Down -- see below; no view template or "
                                     "View Range was changed" % len(self.gaps)))
            self.lines.extend("  GAP " + self.gap_text(v, job, why) for v, job, why in self.gaps)
        if s["room_tags"]:
            self.checks.append(Check("Room tags", True, "%d nudged off a stair path, %d Staircase tag(s) moved back "
                                     "inside the room" % (moved, back)))
        if dims:
            self.checks.append(Check("Dimension strings", None, "%d overlap(s) with a stair path -- not moved, "
                                     "check them in the view" % len(dims)))
            self.lines.extend("  " + d for d in dims[:50])
        self.lines.extend("  Revit " + m for m in self.msgs[:30])
        if action == "trial":
            self.checks.append(Check("Trial -- rolled back", True, "the model is unchanged"))
        else:
            self.checks.append(Check("Applied", True, "one Undo entry in Revit: '%s'. Save / Synchronize to keep it"
                                     % TITLE))
        return self.ok()
'''
